mapper.select:
    select o.orgname as field3DeptName ,o.orgid as field3DeptId,e.* from TBL_CONTROLMATRIX c
left join tbl_risk_coping co on c.RISKCOPINGID=co.RISKCOPINGID
left join tbl_risk r on r.riskid=co.RISKID
left join TBL_CONTROL_ENTRIES e on e.conmatid=c.conmatid 
left join tbl_staff s on s.staffid=e.field13
left join tbl_organization o on o.orgid=s.orgid
where 1=1  and r.unit is not null  and s.orgid is not null

   and r.unit=#{queryParam.linkOrgId}


   and o.orgid=#{queryParam.linkDeptId}


        and e.field4=#{queryParam.field4}


        and e.field11=#{queryParam.field11}

    select o.orgname as field3DeptName ,o.orgid as field3DeptId,e.* from TBL_CONTROLMATRIX c
left join tbl_risk_coping co on c.RISKCOPINGID=co.RISKCOPINGID
left join tbl_risk r on r.riskid=co.RISKID
left join TBL_CONTROL_ENTRIES e on e.conmatid=c.conmatid
left join tbl_organization o on o.orgid=e.LINKORGID
where 1=1  and e.LINKORGID is not null 

   and r.unit=#{queryParam.linkOrgId}


   and o.orgid=#{queryParam.linkDeptId}


        and e.field4=#{queryParam.field4}


        and e.field11=#{queryParam.field11}
